// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockTime, uint64 blockNum, uint64 seed) public {
        vm.assume(blockNum % 15 == 0);
        vm.assume(blockTime > 0);
        vm.warp(blockTime);
        vm.roll(blockNum);

        address sender = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "fallback failed");

        assertTrue(address(c).balance == 0);
    }
}
